using SalesManagement.Core.Auth; using SalesManagement.Core.Exceptions; using SalesManagement.Core.Models; using SalesManagement.Core.Repositories;
namespace SalesManagement.Core.Quotations;
public sealed class QuoteService(IQuoteRepository quotes, ICustomerRepository customers, IInquiryRepository inquiries)
{
    public async Task<IReadOnlyList<Quote>> ListAsync(QuoteQuery query, User actor, CancellationToken ct = default) { AuthorizationService.EnsureActive(actor); var rows = await quotes.ListAsync(ct); return rows.Where(x => (actor.Role == Role.Manager || x.OwnerUserId == actor.Id) && (!query.OwnerId.HasValue || x.OwnerUserId == query.OwnerId) && (!query.CustomerId.HasValue || x.CustomerId == query.CustomerId) && (!query.Status.HasValue || Current(x).Status == query.Status) && (!query.Currency.HasValue || Current(x).Currency == query.Currency) && (string.IsNullOrWhiteSpace(query.Search) || $"{x.QuoteNumber} {x.CustomerName}".Contains(query.Search, StringComparison.OrdinalIgnoreCase))).ToArray(); }
    public async Task<Quote> GetAsync(Guid id, User actor, CancellationToken ct = default) { var row = await quotes.GetAsync(id, ct) ?? throw new KeyNotFoundException(); EnsureOwner(row, actor); return row; }
    public async Task<Quote> CreateAsync(CreateQuoteCommand command, User actor, CancellationToken ct = default)
    {
        if (actor.Role != Role.Manager && command.OwnerId != actor.Id) throw new ForbiddenException();
        if (command.InquiryId.HasValue) { var inquiry = await inquiries.GetAsync(command.InquiryId.Value, ct) ?? throw new KeyNotFoundException(); if (actor.Role != Role.Manager && inquiry.OwnerUserId != actor.Id) throw new ForbiddenException(); }
        var customer = await customers.GetAsync(command.CustomerId, ct) ?? throw new KeyNotFoundException(); var now = DateTime.UtcNow.AddHours(9); var seq = await quotes.NextSequenceAsync(now.Year, now.Month, ct);
        var quote = new Quote { QuoteNumber = $"SWK-{now:yyyyMM}-{seq:000}", InquiryId = command.InquiryId, CustomerId = customer.Id, CustomerName = customer.CompanyName, OwnerUserId = actor.Role == Role.Manager ? command.OwnerId : actor.Id };
        var revision = BuildRevision(quote.Id, 0, command.TradeType, command.Currency, command.TaxType, command.ValidUntil, command.IncotermCode, command.NamedPlace, command.DiscountAmount, command.ShippingAmount, command.OtherAmount, command.Lines); quote.CurrentRevisionId = revision.Id; quote.Revisions.Add(revision); return await quotes.AddAsync(quote, ct);
    }
    public async Task<QuoteRevision> SaveRevisionAsync(Guid quoteId, Guid revisionId, SaveQuoteRevisionCommand command, User actor, CancellationToken ct = default)
    { var quote = await GetAsync(quoteId, actor, ct); var old = Revision(quote, revisionId); if (old.Status is not QuoteStatus.Draft and not QuoteStatus.Rejected) throw new InvalidDataException("승인 요청 이후에는 수정할 수 없습니다."); var next = BuildRevision(quote.Id, old.RevisionNumber, command.TradeType, command.Currency, command.TaxType, command.ValidUntil, command.IncotermCode, command.NamedPlace, command.DiscountAmount, command.ShippingAmount, command.OtherAmount, command.Lines, old.Id, old.Version); if (old.Lines.Count == next.Lines.Count) next.Lines = next.Lines.Select((line, i) => new QuoteLine { Id = old.Lines[i].Id, RevisionId = line.RevisionId, ProductId = line.ProductId, Description = line.Description, Quantity = line.Quantity, UnitPrice = line.UnitPrice, Amount = line.Amount, Version = old.Lines[i].Version }).ToList(); next.Approvals = old.Approvals; next.Dispatches = old.Dispatches; quote.Revisions[quote.Revisions.FindIndex(x => x.Id == old.Id)] = next; await quotes.UpdateAsync(quote, quote.Version, ct); return next; }
    public Task<QuoteRevision> SubmitAsync(Guid quoteId, Guid revisionId, long version, User actor, CancellationToken ct = default) => Transition(quoteId, revisionId, version, actor, QuoteStatus.ApprovalRequested, ct, revision => revision.Approvals.Add(new QuoteApproval { RevisionId = revision.Id, RequestedBy = actor.Id, RequestedAt = DateTimeOffset.UtcNow, Decision = QuoteApprovalDecision.Pending }));
    public Task<QuoteRevision> ApproveAsync(Guid quoteId, Guid revisionId, long version, User actor, CancellationToken ct = default) { AuthorizationService.EnsureManager(actor); return Transition(quoteId, revisionId, version, actor, QuoteStatus.Approved, ct, revision => Decide(revision, actor, QuoteApprovalDecision.Approved, null)); }
    public Task<QuoteRevision> RejectAsync(Guid quoteId, Guid revisionId, string reason, long version, User actor, CancellationToken ct = default) { AuthorizationService.EnsureManager(actor); return Transition(quoteId, revisionId, version, actor, QuoteStatus.Rejected, ct, revision => { revision.RejectionReason = reason; Decide(revision, actor, QuoteApprovalDecision.Rejected, reason); }); }
    public async Task<QuoteRevision> CreateRevisionAsync(Guid quoteId, long version, User actor, CancellationToken ct = default) { var quote = await GetAsync(quoteId, actor, ct); var source = Current(quote); if (source.Status != QuoteStatus.Approved) throw new InvalidDataException("승인된 견적에서만 새 개정을 만들 수 있습니다."); var next = BuildRevision(quote.Id, source.RevisionNumber + 1, source.TradeType, source.Currency, source.TaxType, source.ValidUntil, source.IncotermCode, source.NamedPlace, source.DiscountAmount, source.ShippingAmount, source.OtherAmount, source.Lines.Select(x => new QuoteLineInput(x.ProductId, x.Description, x.Quantity, x.UnitPrice)).ToArray()); quote.Revisions.Add(next); quote.CurrentRevisionId = next.Id; await quotes.UpdateAsync(quote, version, ct); return next; }
    public async Task<QuoteDispatch> RecordDispatchAsync(Guid quoteId, Guid revisionId, RecordDispatchCommand command, User actor, CancellationToken ct = default) { var quote = await GetAsync(quoteId, actor, ct); var revision = Revision(quote, revisionId); if (revision.Status is not QuoteStatus.Approved and not QuoteStatus.Sent) throw new InvalidDataException("승인된 견적만 발송할 수 있습니다."); var item = new QuoteDispatch { RevisionId = revision.Id, SentAt = command.SentAt, Memo = command.Memo, Language = command.Language, RecordedBy = actor.Id }; revision.Dispatches.Add(item); revision.Status = QuoteStatus.Sent; revision.Version++; await quotes.UpdateAsync(quote, quote.Version, ct); return item; }
    public async Task<Quote> RecordResultAsync(Guid quoteId, QuoteStatus result, string? note, long version, User actor, CancellationToken ct = default) { if (result is not QuoteStatus.Won and not QuoteStatus.Lost and not QuoteStatus.OnHold) throw new InvalidDataException("수주, 실주 또는 보류만 기록할 수 있습니다."); var quote = await GetAsync(quoteId, actor, ct); if (Current(quote).Status is not QuoteStatus.Sent and not QuoteStatus.Won and not QuoteStatus.Lost and not QuoteStatus.OnHold) throw new InvalidDataException("발송된 견적만 결과를 기록할 수 있습니다."); quote.Result = result; quote.ResultNote = note; Current(quote).Status = result; return await quotes.UpdateAsync(quote, version, ct); }
    public async Task<QuotePdfModel> GetPdfModelAsync(Guid quoteId, Guid revisionId, QuoteLanguage language, User actor, CancellationToken ct = default) { var quote = await GetAsync(quoteId, actor, ct); var revision = Revision(quote, revisionId); if (revision.Status is not QuoteStatus.Approved and not QuoteStatus.Sent and not QuoteStatus.Won and not QuoteStatus.Lost and not QuoteStatus.OnHold) throw new InvalidDataException("승인된 견적만 PDF로 만들 수 있습니다."); return new(quote.QuoteNumber, $"Rev.{revision.RevisionNumber}", quote.CustomerName, revision.Currency, revision.TotalAmount, revision.IncotermCode, revision.NamedPlace, language, revision.Lines); }
    private async Task<QuoteRevision> Transition(Guid quoteId, Guid revisionId, long version, User actor, QuoteStatus status, CancellationToken ct, Action<QuoteRevision> action) { var quote = await GetAsync(quoteId, actor, ct); var revision = Revision(quote, revisionId); if ((status == QuoteStatus.ApprovalRequested && revision.Status is not QuoteStatus.Draft and not QuoteStatus.Rejected) || (status is QuoteStatus.Approved or QuoteStatus.Rejected && revision.Status != QuoteStatus.ApprovalRequested)) throw new InvalidDataException("허용되지 않는 견적 상태 변경입니다."); if (revision.Version != version) throw new ConcurrencyException(revision.Id, version, revision.Version); action(revision); revision.Status = status; revision.Version++; await quotes.UpdateAsync(quote, quote.Version, ct); return revision; }
    private static QuoteRevision BuildRevision(Guid quoteId, int number, QuoteTradeType trade, Currency currency, QuoteTaxType tax, DateOnly valid, string? code, string? place, decimal discount, decimal shipping, decimal other, IReadOnlyList<QuoteLineInput> inputs, Guid? id = null, long version = 1) { var terms = QuoteCalculator.NormalizeTrade(trade, code, place); var amounts = QuoteCalculator.Calculate(new(currency, tax, discount, shipping, other, inputs)); var revision = new QuoteRevision { Id = id ?? Guid.NewGuid(), QuoteId = quoteId, RevisionNumber = number, TradeType = trade, Currency = currency, TaxType = tax, ValidUntil = valid, IncotermCode = terms.IncotermCode, NamedPlace = terms.NamedPlace, DiscountAmount = discount, ShippingAmount = shipping, OtherAmount = other, SubtotalAmount = amounts.SubtotalAmount, SupplyAmount = amounts.SupplyAmount, TaxAmount = amounts.TaxAmount, TotalAmount = amounts.TotalAmount, Version = version }; revision.Lines = inputs.Select((x, i) => new QuoteLine { RevisionId = revision.Id, ProductId = x.ProductId, Description = x.Description, Quantity = x.Quantity, UnitPrice = x.UnitPrice, Amount = amounts.LineAmounts[i] }).ToList(); return revision; }
    private static QuoteRevision Current(Quote q) => Revision(q, q.CurrentRevisionId); private static QuoteRevision Revision(Quote q, Guid id) => q.Revisions.SingleOrDefault(x => x.Id == id) ?? throw new KeyNotFoundException();
    private static void EnsureOwner(Quote q, User actor) { AuthorizationService.EnsureActive(actor); if (actor.Role != Role.Manager && q.OwnerUserId != actor.Id) throw new ForbiddenException(); }
    private static void Decide(QuoteRevision revision, User actor, QuoteApprovalDecision decision, string? reason) { var approval = revision.Approvals.LastOrDefault(x => x.Decision == QuoteApprovalDecision.Pending) ?? throw new InvalidDataException("승인 요청이 없습니다."); approval.Decision = decision; approval.DecidedBy = actor.Id; approval.DecidedAt = DateTimeOffset.UtcNow; approval.Reason = reason; }
}
